{"base_url":{"scriptActive":true,"script":"var baseURL = "https://awx-linux.prd.openshift.capgv.intra.bnb"
if (fd_data.action_inputs.next_page_link) {
 baseURL += fd_data.action_inputs.next_page_link;
} else {
 baseURL += "/api/v2/jobs/" + fd_data.action_inputs.job_id + "/job_events";
}
return baseURL;"}}

{"resource_path":{"scriptActive":false,"script":"/*
**Access Flow/Action data using the fd_data object. Script must return a value. 
**Order number is offset by +1 in Error Handling Section.
**Available options display upon pressing "." after fd_data
**example: var shortDesc = fd_data.trigger.current.short_description;
**return shortDesc;
*/"}}

sys_variable_value.value:
(function execute(inputs, outputs) {
	try {
		// verifica erro HTTP no REST
		if (![200, 201].includes(inputs.status_code)) {
			throw new Error('Status code da chamada Ansible = ' + inputs.status_code + ' mensagem=' + inputs.status_message);
		}
		if (inputs.error_code != 0) {
			throw new Error('Error code da chamada Ansible=' + inputs.error_code + ' mensagem=' + inputs.error_message);
		}
		// parse REST return - set output vars
		var body = JSON.parse(inputs.response_body);
		var results = body.results;
		var job_template = results[0].summary_fields.job.job_template_id;
		gs.info("EDX DEBUG Processing next page:" + body.next);
		for (i in results) {
			var event_data = results[i].event_data;

			if (results[i].event.startsWith("runner_on") || results[i].event.startsWith("runner_item_on")) {
				if (results[i].failed) {
					var err = 'AWX event failed:' + results[i].event_display + " " + JSON.stringify(results[i]);
					addWorkNotes(err);
					gs.error('EDX ' + err);
				}
				if (results[i].event_data &&
					results[i].event_data.task == "Copy CSR" &&
					results[i].event_data.res &&
					results[i].event_data.res.dest) {
					outputs.csr_path = results[i].event_data.host + ": " + results[i].event_data.res.dest;
					var msg = "Arquivo CSR Foi Gerado em "
						+ event_data.host + ":" + outputs.csr_path;
					addWorkNotes(msg);
					gs.info('EDX ' + msg);
				}
				if (results[i].event_data && results[i].event_data.res && results[i].event_data.res.csr) {
					outputs.csr = results[i].event_data.res.csr;
				}
				if (results[i].event_data && results[i].event_data.res && results[i].event_data.res.csr) {
					outputs.csr = results[i].event_data.res.csr;
				}
			}
		}
		if (body.next) {
			outputs.next_page = body.next;
			outputs.job_status = "processing";
		} else {
			outputs.job_status = results[0].summary_fields.job.status;
			if (outputs.job_status != "successful") {
				addWorkNotes("Job Ansible " + inputs.job_id + " Falhou");
				new global.GlideQuery("sn_disco_certmgmt_task")
					.where("sys_id", inputs.renewal_task.sys_id)
					.update({ state: 3 });
			} else {
				addWorkNotes("Job Ansible " + inputs.job_id + " Completou com sucesso");
			}
		}
	} catch (err) {
		addWorkNotes(err);
		throw 'EDX ' + err;
	}
})(inputs, outputs);

function addWorkNotes(message) {
	var workNoteInputs = {
		task_id: inputs.renewal_task,
		work_notes: ""
	};

	try {
		workNoteInputs.work_notes = message;
		sn_fd.FlowAPI.getRunner().action('sn_disco_certmgmt.update_cert_task_work_notes').inBackground().withInputs(workNoteInputs).run();
	} catch (ex) {
		throw ex;
	}
}

